protocol Movable { var position: Position { get set } }   // capability interface

extension Movable {                     // the servant, written once for all hosts
    mutating func moveTo(_ to: Position) { position = to }
    mutating func moveBy(dx: Int, dy: Int) { moveTo(position.shifted(dx, dy)) }
}

struct Circle: Movable { var position: Position }   // unrelated types, no base class
circle.moveTo(Position(x: 3, y: 4))
